  )
}

pub fn absence_proof_search_valid(proof : AuthMapAbsenceProof) -> Bool {
  if !absence_proof_shape_valid(proof) {
    return false
  }
  for step in proof.path {
    if !absence_step_search_valid(proof.key, step) {
      return false
    }
  }
  true
}

pub fn verify_non_membership(
  hasher : &@bft.Hasher,
  expected_root : @bft.Digest,
  proof : AuthMapAbsenceProof,
) -> Bool {
  if !absence_proof_shape_valid(proof) {
    return false
  }
  let empty_digest = hasher.hash_string(serialize_authmap_empty())
  let mut current = empty_digest
  let mut index = proof.path.length() - 1
  while index >= 0 {
    if !absence_step_search_valid(proof.key, proof.path[index]) {
      return false
    }
    match proof.path[index] {
      DescendedLeft(parent_key, parent_value, right_sibling) =>
        current = hasher.hash_string(
          serialize_authmap_node(
            parent_key, parent_value, current, right_sibling,
          ),
        )
      DescendedRight(parent_key, parent_value, left_sibling) =>
        current = hasher.hash_string(
          serialize_authmap_node(
            parent_key, parent_value, left_sibling, current,
          ),
        )
    }
    index -= 1
  }
  map_root(hasher, proof.entry_count, current) == expected_root
}

pub fn classify_audit_event_time(
  origin_ms~ : Int,
  watermark_ms~ : Int,
  event_time_ms~ : Int,
) -> AuditEventTimeDecision where {
  proof_ensure: decision => {
    audit_event_time_decision_post(
      origin_ms, watermark_ms, event_time_ms, decision,
    )
  },
} {
  let decision = if watermark_ms < origin_ms {
    InvalidAuditWatermark
  } else if event_time_ms < origin_ms {
    AuditEventBeforeOrigin
  } else if event_time_ms < watermark_ms {
    AuditEventBehindWatermark
  } else {
    AuditEventTimeAccepted
  }
  proof_assert audit_event_time_decision_post(
    origin_ms, watermark_ms, event_time_ms, decision,
  )
  decision
}

pub fn classify_checkpoint_head(
  boundary_matches~ : Bool,
  epoch_known~ : Bool,
  known_digest_matches~ : Bool,
  current_epoch~ : Int,
  incoming_epoch~ : Int,
  parent_matches~ : Bool,
) -> CheckpointHeadDecision where {
  proof_ensure: decision => {
    checkpoint_head_decision_post(
      boundary_matches, epoch_known, known_digest_matches, current_epoch, incoming_epoch,
      parent_matches, decision,
    )
  },
} {
  let decision = if !boundary_matches {
    BoundaryMismatch
  } else if epoch_known {
    if known_digest_matches {
      Duplicate
    } else {
      SameEpochFork
    }
  } else if incoming_epoch > current_epoch &&
    incoming_epoch - 1 == current_epoch {
    if parent_matches {
      Advance
    } else {
      ParentFork
    }
  } else if incoming_epoch > current_epoch {
    Gap
  } else {
    Stale
  }
  proof_assert checkpoint_head_decision_post(
    boundary_matches, epoch_known, known_digest_matches, current_epoch, incoming_epoch,
    parent_matches, decision,
  )
  decision
}

pub fn CheckpointHeadDecision::is_fork(self : CheckpointHeadDecision) -> Bool {
  self == SameEpochFork || self == ParentFork
}

pub fn CheckpointHeadDecision::advances(self : CheckpointHeadDecision) -> Bool {
  self == Advance
}

