pub fn open_authenticated_checkpoint_delivery(
  hasher : &@bft.Hasher,
  verifier : &@bft.Verifier,
  policy : DeliveryAuthenticationPolicy,
  signed : SignedCheckpointDelivery,
  approvals : Array[SignedCheckpointDeliveryApproval],
) -> DeliveryAuthenticationResult {
  let statement_valid = checkpoint_delivery_statement_valid(signed.statement)
  if !statement_valid {
    return DeliveryAuthenticationRefused(DeliveryInvalidStatement)
  }
  let policy_valid = checkpoint_delivery_policy_valid(policy)
  if !policy_valid {
    return DeliveryAuthenticationRefused(DeliveryInvalidPolicy)
  }
  let producer_identity_matches = signed.producer_id == policy.producer_id &&
    signed.producer_key == policy.producer_key
  if !producer_identity_matches {
    return DeliveryAuthenticationRefused(DeliveryProducerIdentityMismatch)
  }
  let expected_digest = hasher.hash_string(
    serialize_checkpoint_delivery_statement(signed.statement),
  )
  if expected_digest != signed.digest {
    return DeliveryAuthenticationRefused(DeliveryStatementDigestMismatch)
  }
  let producer_signature_valid = verifier.verify(
    signed.producer_key,
    signed.digest,
    signed.signature,
  )
  if !producer_signature_valid {
    return DeliveryAuthenticationRefused(DeliveryInvalidProducerSignature)
  }
  let witness_keys : Map[String, @bft.PublicKey] = Map([])
  for witness in policy.witnesses {
    witness_keys[witness.witness_id] = witness.witness_key
  }
  let approved : Map[String, Bool] = Map([])
  for approval in approvals {
    if approval.statement_digest != signed.digest {
      return DeliveryAuthenticationRefused(DeliveryApprovalStatementMismatch)
    }
    if approved.contains(approval.witness_id) {
      return DeliveryAuthenticationRefused(DeliveryDuplicateWitness)
    }
    let expected_key = match witness_keys.get(approval.witness_id) {
      Some(key) => key
      None => return DeliveryAuthenticationRefused(DeliveryUnknownWitness)
    }
    if approval.witness_key != expected_key {
      return DeliveryAuthenticationRefused(DeliveryWitnessKeyMismatch)
    }
    let expected_approval_digest = hasher.hash_string(
      serialize_checkpoint_delivery_approval(
        approval.statement_digest,
        approval.witness_id,
      ),
    )
    if approval.digest != expected_approval_digest {
      return DeliveryAuthenticationRefused(DeliveryApprovalDigestMismatch)
    }
    if !verifier.verify(
        approval.witness_key,
        approval.digest,
        approval.signature,
      ) {
      return DeliveryAuthenticationRefused(DeliveryInvalidWitnessSignature)
    }
    approved[approval.witness_id] = true
  }
  let approval_count = approved.length()
  let quorum_satisfied = approval_count >= policy.required_approvals
  if !quorum_satisfied {
    return DeliveryAuthenticationRefused(
      DeliveryUnderQuorum(approval_count, policy.required_approvals),
    )
  }
  if !@audit.runtime_checkpoint_delivery_authentication_allowed(
      statement_valid, policy_valid, producer_identity_matches, producer_signature_valid,
      true, quorum_satisfied,
    ) {
    abort("checkpoint delivery authentication gate diverged")
  }
  DeliveryAuthenticated(AuthenticatedCheckpointDelivery::{
    statement_value: signed.statement,
    producer_id_value: signed.producer_id,
    approval_count_value: approval_count,
  })
}

pub fn select_peer_delivery_batch(
  routes : Array[PeerRouteState],
  now_ms~ : Int,
  in_flight_count~ : Int,
  max_in_flight~ : Int,
  max_parallel~ : Int,
) -> PeerDeliverySelectionResult {
  if now_ms < 0 ||
    in_flight_count < 0 ||
    max_in_flight <= 0 ||
    max_parallel <= 0 ||
    in_flight_count > max_in_flight {
    return PeerDeliveryRefused(InvalidPeerDeliveryWindow)
  }
  let seen : Map[String, Bool] = Map([])
  let eligible : Array[(Int, PeerRouteState)] = []
  for index, route in routes {
    if !peer_route_valid(route) {
      return PeerDeliveryRefused(InvalidPeerRoute(index))
    }
    if seen.contains(route.peer_id) {
      return PeerDeliveryRefused(DuplicatePeerRoute)
    }
    seen[route.peer_id] = true
    if route.available && !route.quarantined && route.next_retry_at_ms <= now_ms {
      eligible.push((index, route))
    }
  }
  let capacity = max_in_flight - in_flight_count
  if capacity == 0 {
    return PeerDeliveryBackpressured
  }
  if eligible.length() == 0 {
    return PeerDeliveryUnavailable
  }
  eligible.sort_by(fn(left, right) {
    if peer_route_precedes(left.1, right.1) {
      -1
    } else if peer_route_precedes(right.1, left.1) {
      1
    } else {
      0
    }
  })
  let limit = if capacity < max_parallel { capacity } else { max_parallel }
  let selected : Array[Int] = []
  for index = 0; index < eligible.length() && index < limit; index = index + 1 {
    selected.push(eligible[index].0)
  }
  PeerDeliverySelected(selected)
}

pub fn record_peer_delivery_failure(
  route : PeerRouteState,
  now_ms~ : Int,
  attempt_order~ : Int,
  base_backoff_ms~ : Int,
  max_backoff_ms~ : Int,
) -> PeerRouteUpdateResult {
  if !peer_route_valid(route) ||
    route.quarantined ||
    now_ms < 0 ||
    attempt_order <= route.last_attempt_order ||
    base_backoff_ms <= 0 ||
    max_backoff_ms < base_backoff_ms {
    return PeerRouteUpdateRefused
  }
  let delay = bounded_exponential_backoff(
    route.failures,
    base_backoff_ms,
    max_backoff_ms,
  )
  let retry_at = now_ms + delay
  if retry_at < now_ms || route.failures == 2147483647 {
    return PeerRouteUpdateRefused
  }
  PeerRouteUpdated({
    ..route,
    failures: route.failures + 1,
    next_retry_at_ms: retry_at,
    last_attempt_order: attempt_order,
  })
}

pub fn record_peer_delivery_success(
  route : PeerRouteState,
  attempt_order~ : Int,
) -> PeerRouteUpdateResult {
  if !peer_route_valid(route) ||
    route.quarantined ||
    attempt_order <= route.last_attempt_order {
    return PeerRouteUpdateRefused
  }
  PeerRouteUpdated({
    ..route,
    available: true,
    failures: 0,
    next_retry_at_ms: 0,
    last_attempt_order: attempt_order,
  })
}

pub fn select_peer_checkpoint_response(
  responses : Array[PeerCheckpointResponse],
  expected_digest~ : @commitment.AuditDigest,
) -> PeerCheckpointResponseSelection {
  if expected_digest.0 == "" {
    return PeerCheckpointResponseRefused
  }
  let seen : Map[String, Bool] = Map([])
  let mut selected = -1
  let mut fork_count = 0
  for index, response in responses {
    if response.peer_id == "" || response.received_at_ms < 0 {
      return PeerCheckpointResponseRefused
    }
    if seen.contains(response.peer_id) {
      return PeerCheckpointResponseRefused
    }
    seen[response.peer_id] = true
    if response.authenticated {
      if response.checkpoint_digest != expected_digest {
        fork_count += 1
      } else if selected < 0 ||
        response.received_at_ms < responses[selected].received_at_ms ||
        (
          response.received_at_ms == responses[selected].received_at_ms &&
          response.peer_id.compare(responses[selected].peer_id) < 0
        ) {
        selected = index
      }
    }
  }
  if fork_count > 0 {
    PeerCheckpointForkDetected(fork_count)
  } else if selected >= 0 {
    PeerCheckpointResponseAccepted(selected)
  } else {
    PeerCheckpointResponseUnavailable
  }
}

