      None => ()
      Some(event_proof) =>
        match self.tree.proof(index) {
          None => return None
          Some(micro_proof) =>
            return Some({
              micro_checkpoint: micro.checkpoint_value,
              event_proof,
              micro_proof,
            })
        }
    }
  }
