pub fn classify_historical_key_admission(
  key_binding_matches~ : Bool,
  key_version~ : Int,
  key_valid_from_ms~ : Int,
  key_valid_until_ms~ : Int,
  key_revoked~ : Bool,
  key_revoked_at_ms~ : Int,
  statement_issued_at_ms~ : Int,
  verification_time_ms~ : Int,
  max_clock_skew_ms~ : Int,
  scheme_supported~ : Bool,
  signature_valid~ : Bool,
) -> HistoricalKeyAdmissionDecision where {
  proof_ensure: decision => {
    historical_key_admission_post(
      key_binding_matches, key_version, key_valid_from_ms, key_valid_until_ms, key_revoked,
      key_revoked_at_ms, statement_issued_at_ms, verification_time_ms, max_clock_skew_ms,
      scheme_supported, signature_valid, decision,
    )
  },
} {
  let metadata_valid = key_version > 0 &&
    key_valid_from_ms >= 0 &&
    key_valid_until_ms > key_valid_from_ms &&
    statement_issued_at_ms >= 0 &&
    verification_time_ms >= 0 &&
    max_clock_skew_ms >= 0
  let decision = if !metadata_valid {
    RejectHistoricalKeyMetadata
  } else if !key_binding_matches {
    RejectHistoricalKeyBinding
  } else if statement_issued_at_ms > verification_time_ms + max_clock_skew_ms {
    RejectHistoricalKeyStatementFromFuture
  } else if statement_issued_at_ms < key_valid_from_ms {
    RejectHistoricalKeyNotYetValidAtIssuance
  } else if statement_issued_at_ms >= key_valid_until_ms {
    RejectHistoricalKeyExpiredAtIssuance
  } else if key_revoked && statement_issued_at_ms >= key_revoked_at_ms {
    RejectHistoricalKeyRevokedAtIssuance
  } else if !scheme_supported {
    RejectHistoricalKeyScheme
  } else if !signature_valid {
    RejectHistoricalKeySignature
  } else {
    AdmitHistoricalKey
  }
  proof_assert historical_key_admission_post(
    key_binding_matches, key_version, key_valid_from_ms, key_valid_until_ms, key_revoked,
    key_revoked_at_ms, statement_issued_at_ms, verification_time_ms, max_clock_skew_ms,
    scheme_supported, signature_valid, decision,
  )
  decision
}

pub fn serialize_vote_statement(statement : VoteStatement) -> String {
  let buffer = StringBuilder::new()
  quorum_append_field(buffer, "attestation-v2")
  quorum_append_field(buffer, statement.subject_digest.0)
  quorum_append_field(buffer, statement.member_id)
  quorum_append_field(buffer, statement.domain)
  buffer.write_char(
    match statement.choice {
      ApproveChoice => 'A'
      ChallengeChoice => 'C'
    },
  )
  buffer.to_string()
}

pub fn sign_vote(
  hasher : &@bft.Hasher,
  signer : &@bft.Signer,
  subject_digest : @bft.Digest,
  member_id : String,
  domain : String,
  choice : VoteChoice,
) -> SignedVote {
  let statement = VoteStatement::{ subject_digest, member_id, domain, choice }
  let digest = hasher.hash_string(serialize_vote_statement(statement))
  {
    statement,
    digest,
    signature: signer.sign(digest),
    signer_key: signer.public_key(),
  }
}

pub fn VoteCollector::new(
  hasher : &@bft.Hasher,
  verifier : &@bft.Verifier,
  subject_digest : @bft.Digest,
  domain : String,
  members : Array[QuorumMember],
) -> VoteCollector {
  let member_keys : Map[String, @bft.PublicKey] = Map([])
  let member_indices : Map[String, Int] = Map([])
  let used_keys : Map[String, Bool] = Map([])
  let mut roster_valid = subject_digest.0 != "" && domain != ""
  for index, roster_entry in members {
    if roster_entry.member_id == "" ||
      roster_entry.member_key.0 == "" ||
      member_keys.contains(roster_entry.member_id) ||
      used_keys.contains(roster_entry.member_key.0) {
      roster_valid = false
    } else {
      member_keys[roster_entry.member_id] = roster_entry.member_key
      member_indices[roster_entry.member_id] = index
      used_keys[roster_entry.member_key.0] = true
    }
  }
  VoteCollector::{
    hasher,
    verifier,
    subject_digest_value: subject_digest,
    domain_value: domain,
    member_keys,
    member_indices,
    votes: Array::make(members.length(), @quorum_vote.ParticipantVote::NoVote),
    roster_valid_value: roster_valid,
  }
}

