pub fn VoteCollector::deliver(
  self : VoteCollector,
  signed : SignedVote,
) -> VoteDeliveryResult {
  if !self.roster_valid_value {
    return vote_rejection(
      VoteInvalidRoster,
      signed,
      "quorum roster or collector subject is invalid",
    )
  }
  let recomputed = self.hasher.hash_string(
    serialize_vote_statement(signed.statement),
  )
  if recomputed != signed.digest {
    return vote_rejection(VoteHashMismatch, signed, "vote digest mismatch")
  }
  if signed.statement.domain != self.domain_value {
    return vote_rejection(
      VoteWrongDomain,
      signed,
      "vote belongs to a different protocol domain",
    )
  }
  let member_id = signed.statement.member_id
  let index = match self.member_indices.get(member_id) {
    None =>
      return vote_rejection(
        VoteUnknownMember,
        signed,
        "member is absent from the configured roster",
      )
    Some(index) => index
  }
  let expected_key = match self.member_keys.get(member_id) {
    None =>
      return vote_rejection(
        VoteInvalidRoster,
        signed,
        "member index has no signing key",
      )
    Some(key) => key
  }
  if expected_key != signed.signer_key {
    return vote_rejection(
      VoteSignerKeyMismatch,
      signed,
      "vote signer does not own the member id",
    )
  }
  if !self.verifier.verify(signed.signer_key, signed.digest, signed.signature) {
    return vote_rejection(
      VoteInvalidSignature,
      signed,
      "vote signature verification failed",
    )
  }
  if signed.statement.subject_digest != self.subject_digest_value {
    return vote_rejection(
      VoteWrongSubject,
      signed,
      "vote targets a different subject",
    )
  }
  let current = self.votes[index]
  let incoming = match signed.statement.choice {
    ApproveChoice => @quorum_vote.ParticipantVote::ApproveVote
    ChallengeChoice => @quorum_vote.ParticipantVote::ChallengeVote
  }
  let merged = @quorum_vote.merge_participant_votes(current, incoming)
  if merged == current {
    return VoteDuplicate
  }
  self.votes[index] = merged
  if merged == @quorum_vote.ParticipantVote::EquivocatedVote {
    return vote_rejection(
      VoteEquivocation,
      signed,
      "member signed conflicting choices",
    )
  }
  VoteAccepted
}

pub fn VoteCollector::evidence(self : VoteCollector) -> QuorumEvidence {
  let approvals : Array[Bool] = []
  let mut challenged = !self.roster_valid_value
  for vote in self.votes {
    approvals.push(self.roster_valid_value && vote.is_approval())
    if vote.is_challenge() {
      challenged = true
    }
  }
  { approvals: FixedArray::from_array(approvals[:]), challenged }
}

pub fn select_peer_delivery_batch(
  routes : Array[PeerRouteState],
  now_ms~ : Int,
  in_flight_count~ : Int,
  max_in_flight~ : Int,
  max_parallel~ : Int,
) -> PeerDeliverySelectionResult {
  if now_ms < 0 ||
    in_flight_count < 0 ||
    max_in_flight <= 0 ||
    max_parallel <= 0 ||
    in_flight_count > max_in_flight {
    return PeerDeliveryRefused(InvalidPeerDeliveryWindow)
  }
  let seen : Map[String, Bool] = Map([])
  let eligible : Array[(Int, PeerRouteState)] = []
  for index, route in routes {
    if !peer_route_valid(route) {
      return PeerDeliveryRefused(InvalidPeerRoute(index))
    }
    if seen.contains(route.peer_id) {
      return PeerDeliveryRefused(DuplicatePeerRoute)
    }
    seen[route.peer_id] = true
    if route.available && !route.quarantined && route.next_retry_at_ms <= now_ms {
      eligible.push((index, route))
    }
  }
  let capacity = max_in_flight - in_flight_count
  if capacity == 0 {
    return PeerDeliveryBackpressured
  }
  if eligible.length() == 0 {
    return PeerDeliveryUnavailable
  }
  eligible.sort_by(fn(left, right) {
    if peer_route_precedes(left.1, right.1) {
      -1
    } else if peer_route_precedes(right.1, left.1) {
      1
    } else {
      0
    }
  })
  let limit = if capacity < max_parallel { capacity } else { max_parallel }
  let selected : Array[Int] = []
  for index = 0; index < eligible.length() && index < limit; index = index + 1 {
    selected.push(eligible[index].0)
  }
  PeerDeliverySelected(selected)
}

pub fn record_peer_delivery_failure(
  route : PeerRouteState,
  now_ms~ : Int,
  attempt_order~ : Int,
  base_backoff_ms~ : Int,
  max_backoff_ms~ : Int,
) -> PeerRouteUpdateResult {
  if !peer_route_valid(route) ||
    route.quarantined ||
    now_ms < 0 ||
    attempt_order <= route.last_attempt_order ||
    base_backoff_ms <= 0 ||
    max_backoff_ms < base_backoff_ms {
    return PeerRouteUpdateRefused
  }
  let delay = bounded_exponential_backoff(
    route.failures,
    base_backoff_ms,
    max_backoff_ms,
  )
  let retry_at = now_ms + delay
  if retry_at < now_ms || route.failures == 2147483647 {
    return PeerRouteUpdateRefused
  }
  PeerRouteUpdated({
    ..route,
    failures: route.failures + 1,
    next_retry_at_ms: retry_at,
    last_attempt_order: attempt_order,
  })
}

pub fn record_peer_delivery_success(
  route : PeerRouteState,
  attempt_order~ : Int,
) -> PeerRouteUpdateResult {
  if !peer_route_valid(route) ||
    route.quarantined ||
    attempt_order <= route.last_attempt_order {
    return PeerRouteUpdateRefused
  }
  PeerRouteUpdated({
    ..route,
    available: true,
    failures: 0,
    next_retry_at_ms: 0,
    last_attempt_order: attempt_order,
  })
}

pub fn select_peer_checkpoint_response(
  responses : Array[PeerCheckpointResponse],
  expected_digest~ : @commitment.AuditDigest,
) -> PeerCheckpointResponseSelection {
  if expected_digest.0 == "" {
    return PeerCheckpointResponseRefused
  }
  let seen : Map[String, Bool] = Map([])
  let mut selected = -1
  let mut fork_count = 0
  for index, response in responses {
    if response.peer_id == "" || response.received_at_ms < 0 {
      return PeerCheckpointResponseRefused
    }
    if seen.contains(response.peer_id) {
      return PeerCheckpointResponseRefused
    }
    seen[response.peer_id] = true
    if response.authenticated {
      if response.checkpoint_digest != expected_digest {
        fork_count += 1
      } else if selected < 0 ||
        response.received_at_ms < responses[selected].received_at_ms ||
        (
          response.received_at_ms == responses[selected].received_at_ms &&
          response.peer_id.compare(responses[selected].peer_id) < 0
        ) {
        selected = index
      }
    }
  }
  if fork_count > 0 {
    PeerCheckpointForkDetected(fork_count)
  } else if selected >= 0 {
    PeerCheckpointResponseAccepted(selected)
  } else {
    PeerCheckpointResponseUnavailable
  }
}

