}

pub fn SealedMacroCheckpoint::event_proof(
  self : SealedMacroCheckpoint,
  canonical_payload : String,
) -> LayeredEventProof? {
  for index, micro in self.micro_values {
    match micro.event_proof(canonical_payload) {
      None => ()
      Some(event_proof) =>
        match self.tree.proof(index) {
          None => return None
          Some(micro_proof) =>
            return Some({
              micro_checkpoint: micro.checkpoint_value,
              event_proof,
              micro_proof,
            })
        }
    }
  }
  None
}

pub fn verify_micro_checkpoint_event(
  hasher : &@bft.Hasher,
  checkpoint : MicroCheckpoint,
  canonical_payload : String,
  proof : @merkle.MerkleProof,
) -> Bool {
  if checkpoint.event_count <= 0 ||
    checkpoint.ends_at_ms <= checkpoint.starts_at_ms ||
    proof.leaf_count != checkpoint.event_count ||
    micro_checkpoint_digest(hasher, checkpoint) != checkpoint.digest {
    return false
  }
  @merkle.verify_inclusion(
    hasher,
    canonical_payload,
    checkpoint.event_root,
    proof,
  )
}

pub fn player_local_evidence_poll_lease_expiry(
  now_ms : Int,
  deadline_at_ms : Int,
  lease_duration_ms : Int,
) -> Int {
  if now_ms < 0 || deadline_at_ms <= now_ms || lease_duration_ms <= 0 {
    return -1
  }
  let requested = now_ms + lease_duration_ms
  if requested <= now_ms {
    -1
  } else if requested > deadline_at_ms {
    deadline_at_ms
  } else {
    requested
  }
}

pub fn player_local_evidence_poll_backoff_delay(
  failures : Int,
  base_backoff_ms : Int,
  max_backoff_ms : Int,
) -> Int {
  if failures < 0 || base_backoff_ms <= 0 || max_backoff_ms < base_backoff_ms {
    return -1
  }
  let mut delay = base_backoff_ms
  let mut remaining = failures
  while remaining > 0 && delay < max_backoff_ms {
    delay = if delay > max_backoff_ms / 2 { max_backoff_ms } else { delay * 2 }
    remaining -= 1
  }
  if delay > max_backoff_ms {
    max_backoff_ms
  } else {
    delay
  }
}

pub fn player_local_evidence_poll_next_retry_at(
  now_ms : Int,
  deadline_at_ms : Int,
  failures : Int,
  base_backoff_ms : Int,
  max_backoff_ms : Int,
) -> Int {
  if now_ms < 0 || deadline_at_ms <= now_ms {
    return -1
  }
  let delay = player_local_evidence_poll_backoff_delay(
    failures, base_backoff_ms, max_backoff_ms,
  )
  if delay < 0 {
    return -1
  }
  let requested = now_ms + delay
  if requested <= now_ms {
    -1
  } else if requested > deadline_at_ms {
    deadline_at_ms
  } else {
    requested
  }
}

