pub fn audit_select_peer_checkpoint_response(
  peer_ids : Array[String],
  checkpoint_digests : Array[String],
  authenticated : Array[Bool],
  received_at_ms : Array[Int],
  expected_digest : String,
) -> String {
  let count = peer_ids.length()
  if checkpoint_digests.length() != count ||
    authenticated.length() != count ||
    received_at_ms.length() != count {
    return Json::object({ "decision": Json::string("refused") }).stringify()
  }
  let responses : Array[@audit_runtime.PeerCheckpointResponse] = []
  for index = 0; index < count; index = index + 1 {
    responses.push({
      peer_id: peer_ids[index],
      checkpoint_digest: @commitment.AuditDigest(checkpoint_digests[index]),
      authenticated: authenticated[index],
      received_at_ms: received_at_ms[index],
    })
  }
  match
    @audit_runtime.select_peer_checkpoint_response(
      responses,
      expected_digest=@commitment.AuditDigest(expected_digest),
    ) {
    @audit_runtime.PeerCheckpointResponseSelection::PeerCheckpointResponseAccepted(
      index
    ) =>
      Json::object({
        "decision": Json::string("accepted"),
        "index": Json::number(index.to_double()),
      }).stringify()
    @audit_runtime.PeerCheckpointResponseSelection::PeerCheckpointForkDetected(
      count
    ) =>
      Json::object({
        "decision": Json::string("fork_detected"),
        "fork_count": Json::number(count.to_double()),
      }).stringify()
    @audit_runtime.PeerCheckpointResponseSelection::PeerCheckpointResponseUnavailable =>
      Json::object({ "decision": Json::string("unavailable") }).stringify()
    @audit_runtime.PeerCheckpointResponseSelection::PeerCheckpointResponseRefused =>
      Json::object({ "decision": Json::string("refused") }).stringify()
  }
}

pub fn audit_acknowledge_checkpoint_outbox(
  protocol_version : Int,
  purpose : String,
  manifest_digest : String,
  scope_id : String,
  unit_id : String,
  destination_id : String,
  epoch : Int,
  checkpoint_digest : String,
  canonical_envelope : String,
  created_order : Int,
  ack_protocol_version : Int,
  ack_purpose : String,
  ack_manifest_digest : String,
  ack_scope_id : String,
  ack_unit_id : String,
  ack_authority_id : String,
  ack_epoch : Int,
  ack_checkpoint_digest : String,
  ack_decision : String,
  authentication_succeeded : Bool,
) -> String {
  let boundary = bridge_boundary(
    protocol_version, purpose, manifest_digest, scope_id, unit_id,
  )
  let entry = match
    @audit_runtime.open_checkpoint_outbox_entry(
      boundary~,
      destination_id~,
      epoch~,
      checkpoint_digest=@commitment.AuditDigest(checkpoint_digest),
      canonical_envelope~,
      created_order~,
    ) {
    @audit_runtime.CheckpointOutboxOpenResult::OutboxEntryReady(value) => value
    @audit_runtime.CheckpointOutboxOpenResult::OutboxEntryRefused(_) =>
      return "refused_invalid_outbox_entry"
  }
  let decision = match bridge_checkpoint_ack_decision(ack_decision) {
    Some(value) => value
    None => return "refused_invalid_ack_decision"
  }
  let ack_boundary = bridge_boundary(
    ack_protocol_version, ack_purpose, ack_manifest_digest, ack_scope_id, ack_unit_id,
  )
  let evidence = @audit_runtime.CheckpointAckEvidence::{
    boundary: ack_boundary,
    authority_id: ack_authority_id,
    epoch: ack_epoch,
    checkpoint_digest: @commitment.AuditDigest(ack_checkpoint_digest),
    decision,
  }
  let ack = match
    @audit_runtime.open_authenticated_checkpoint_ack(
      evidence,
      authentication_succeeded~,
    ) {
    @audit_runtime.CheckpointAckOpenResult::CheckpointAckReady(value) => value
    @audit_runtime.CheckpointAckOpenResult::CheckpointAckRefused(reason) =>
      return "refused_" + bridge_checkpoint_ack_open_refusal_code(reason)
  }
  match @audit_runtime.acknowledge_checkpoint_outbox(entry, ack) {
    @audit_runtime.CheckpointOutboxAckResult::OutboxAcknowledged(_) =>
      "acknowledged"
    @audit_runtime.CheckpointOutboxAckResult::OutboxAlreadyAcknowledged =>
      "already_acknowledged"
    @audit_runtime.CheckpointOutboxAckResult::OutboxAckRefused(reason) =>
      "refused_" + bridge_outbox_ack_refusal_code(reason)
  }
}

pub fn serialize_authmap_empty() -> String {
  tagged_preimage("authmap-empty-v1", [])
}

pub fn serialize_authmap_node(
  key : String,
  value : String,
  left_digest : @bft.Digest,
  right_digest : @bft.Digest,
) -> String {
  tagged_preimage("authmap-node-v1", [key, value, left_digest.0, right_digest.0])
}

pub fn serialize_authmap_root(
  entry_count : Int,
  node_digest : @bft.Digest,
) -> String {
  tagged_preimage("authmap-root-v1", [entry_count.to_string(), node_digest.0])
}

pub fn AuthenticatedMap::new(hasher : &@bft.Hasher) -> AuthenticatedMap {
  AuthenticatedMap::{
    hasher,
    empty_digest: hasher.hash_string(serialize_authmap_empty()),
    root_node: Empty,
    entry_count: 0,
  }
}

pub fn AuthenticatedMap::fork(self : AuthenticatedMap) -> AuthenticatedMap {
  AuthenticatedMap::{
    hasher: self.hasher,
    empty_digest: self.empty_digest,
    root_node: self.root_node,
    entry_count: self.entry_count,
  }
}

pub fn AuthenticatedMap::put(
  self : AuthenticatedMap,
  key : String,
  value : String,
) -> AuthMapMutation {
  let changed = put_node(
    self.hasher,
    self.empty_digest,
    self.root_node,
    key,
    value,
  )
  self.root_node = changed.0
  if changed.1 {
    self.entry_count += 1
    Inserted
  } else if changed.2 {
    Updated
  } else {
    Unchanged
  }
}

pub fn AuthenticatedMap::remove(self : AuthenticatedMap, key : String) -> Bool {
  let removed = remove_node(self.hasher, self.empty_digest, self.root_node, key)
  self.root_node = removed.0
  if removed.1 {
    self.entry_count -= 1
  }
  removed.1
}

pub fn AuthenticatedMap::get(self : AuthenticatedMap, key : String) -> String? {
  let mut node = self.root_node
  while true {
    match node {
      Empty => return None
      Branch(node_key, value, _, _, left, right) => {
        let order = key.compare(node_key)
        if order == 0 {
          return Some(value)
        }
        node = if order < 0 { left } else { right }
      }
    }
  }
  None
}

pub fn AuthenticatedMap::root(self : AuthenticatedMap) -> @bft.Digest {
  map_root(
    self.hasher,
    self.entry_count,
    self.root_node.digest(self.empty_digest),
  )
}

pub fn AuthenticatedMap::size(self : AuthenticatedMap) -> Int {
  self.entry_count
}

pub fn AuthenticatedMap::proof(
  self : AuthenticatedMap,
  key : String,
) -> AuthMapProof? {
  collect_proof(self.root_node, self.empty_digest, key, self.entry_count, [])
}

pub fn AuthenticatedMap::absence_proof(
  self : AuthenticatedMap,
  key : String,
) -> AuthMapAbsenceProof? {
  collect_absence_proof(
    self.root_node,
    self.empty_digest,
    key,
    self.entry_count,
    [],
  )
}

pub fn verify_membership(
  hasher : &@bft.Hasher,
  expected_root : @bft.Digest,
  proof : AuthMapProof,
) -> Bool {
  if proof.entry_count <= 0 {
    return false
  }
  let mut current = hasher.hash_string(
    serialize_authmap_node(
      proof.key,
      proof.value,
      proof.left_digest,
      proof.right_digest,
    ),
  )
  let mut index = proof.path.length() - 1
  while index >= 0 {
    match proof.path[index] {
      DescendedLeft(parent_key, parent_value, right_sibling) => {
        if proof.key.compare(parent_key) >= 0 {
          return false
        }
        current = hasher.hash_string(
          serialize_authmap_node(
            parent_key, parent_value, current, right_sibling,
          ),
        )
      }
      DescendedRight(parent_key, parent_value, left_sibling) => {
        if proof.key.compare(parent_key) <= 0 {
          return false
        }
        current = hasher.hash_string(
          serialize_authmap_node(
            parent_key, parent_value, left_sibling, current,
          ),
        )
      }
    }
    index -= 1
  }
  map_root(hasher, proof.entry_count, current) == expected_root
}

pub fn membership_verification_plan(
  hasher : &@bft.Hasher,
  proof : AuthMapProof,
) -> AuthMapHashVerificationPlan {
  authmap_hash_verification_plan(
    hasher,
    proof.entry_count,
    proof.path,
    serialize_authmap_node(
      proof.key,
      proof.value,
      proof.left_digest,
      proof.right_digest,
    ),
  )
}

pub fn non_membership_verification_plan(
  hasher : &@bft.Hasher,
  proof : AuthMapAbsenceProof,
) -> AuthMapHashVerificationPlan {
  authmap_hash_verification_plan(
    hasher,
    proof.entry_count,
    proof.path,
    serialize_authmap_empty(),
  )
}

pub fn absence_proof_search_valid(proof : AuthMapAbsenceProof) -> Bool {
  if !absence_proof_shape_valid(proof) {
    return false
  }
  for step in proof.path {
    if !absence_step_search_valid(proof.key, step) {
      return false
    }
  }
  true
}

pub fn verify_non_membership(
  hasher : &@bft.Hasher,
  expected_root : @bft.Digest,
  proof : AuthMapAbsenceProof,
) -> Bool {
  if !absence_proof_shape_valid(proof) {
    return false
  }
  let empty_digest = hasher.hash_string(serialize_authmap_empty())
  let mut current = empty_digest
  let mut index = proof.path.length() - 1
  while index >= 0 {
    if !absence_step_search_valid(proof.key, proof.path[index]) {
      return false
    }
    match proof.path[index] {
      DescendedLeft(parent_key, parent_value, right_sibling) =>
        current = hasher.hash_string(
          serialize_authmap_node(
            parent_key, parent_value, current, right_sibling,
          ),
        )
      DescendedRight(parent_key, parent_value, left_sibling) =>
        current = hasher.hash_string(
          serialize_authmap_node(
            parent_key, parent_value, left_sibling, current,
          ),
        )
    }
    index -= 1
  }
  map_root(hasher, proof.entry_count, current) == expected_root
}
